/**
 * The brand palettes — the single source of truth for every colour the app
 * themes itself with, and for the colours the logo mark is drawn in.
 *
 * A palette carries ten brand tokens rather than a full UI palette. The 26 UI
 * variables are *derived* from those ten in `assets/themes.css` (generated by
 * `scripts/build-themes.mjs`), so adding a theme means picking ten colours,
 * not authoring twenty-six. Anything the derivation gets wrong for a specific
 * palette can be pinned via `pin`.
 *
 * Deliberately framework-free and value-import-free: `scripts/build-icon.cjs`
 * loads this file inside Electron through a one-shot esbuild transform, so it
 * must not pull in anything that isn't plain data.
 */

export type PaletteId =
  | 'arcane-gold'
  | 'ember-slate'
  | 'verdant-brass'
  | 'violet-ink'
  | 'midnight-cyan'
  | 'parchment-inverted'
  | 'steel-amber'
  | 'plum-mint'
  | 'phb'
  | 'light';

/** Light or dark ground. Drives the semantic colour step and `data-scheme`. */
export type Scheme = 'light' | 'dark';

/** The six roles the mark's shapes are painted with. */
export interface MarkRoles {
  back1: string;
  back2: string;
  front: string;
  dot: string;
  accent: string;
  bar2: string;
}

export interface BrandPalette {
  id: PaletteId;
  label: string;
  /** One line for the settings picker. */
  note: string;
  scheme: Scheme;
  /** "brand" palettes are the new set; "paper" are the two kept originals. */
  group: 'brand' | 'paper';

  // ---- the ten brand tokens ------------------------------------------------
  /** Ground behind the mark when it sits on its own tile (the app icon). */
  tile: string;
  /** The app background — and the ground the mark is composed against. */
  ground: string;
  back1: string;
  back2: string;
  front: string;
  dot: string;
  accent: string;
  bar2: string;
  text: string;
  textMuted: string;
  /**
   * The current-turn highlight. Deliberately NOT the accent: the accent marks
   * the active tab and primary buttons, and if whose-turn-it-is shared that
   * colour the busiest signal on the combat screen would stop standing out.
   */
  turn: string;

  /**
   * How the mark is painted when it sits directly on the theme's panel rather
   * than on its tile — light cards on a dark sidebar, dark cards on a light
   * one. This is the sidebar lock-up's role assignment.
   */
  on: MarkRoles;

  /** UI variables this palette overrides instead of deriving. */
  pin?: Record<string, string>;
}

