/** The palette a fresh install starts on, and the one the app icon is drawn in. */
export const DEFAULT_PALETTE: PaletteId = 'violet-ink';

export const PALETTE_BY_ID: Record<string, BrandPalette> = Object.fromEntries(
  PALETTES.map((p) => [p.id, p]),
);

/**
 * Theme ids from before the rebrand. `electron` was violet with a gold-ish
 * accent and `dark` was the neutral one, so each maps to its closest heir;
 * `phb` and `light` kept their ids and need no mapping.
 */
export const LEGACY_THEME_MAP: Record<string, PaletteId> = {
  electron: 'arcane-gold',
  dark: 'violet-ink',
};

/** Coerces any stored value to a live palette id. */
export function migrateThemeId(stored: unknown): PaletteId {
  if (typeof stored !== 'string') return DEFAULT_PALETTE;
  if (stored in PALETTE_BY_ID) return stored as PaletteId;
  return LEGACY_THEME_MAP[stored] ?? DEFAULT_PALETTE;
}

/** The window background before the first paint, so launch doesn't flash. */
export function groundFor(theme: unknown): string {
  return PALETTE_BY_ID[migrateThemeId(theme)].ground;
}
